en={'menu':'MENU','nav1':'Our cultures','nav2':'Slow by nature','nav3':'Build a tasting box','small':'A LITTLE CULTURE, EVERY DAY.','hero':'CULTURED','yogurt':'01 / SET YOGURT','kefir':'02 / SLOW KEFIR','labneh':'03 / SOFT LABNEH','yd':'Milk. Culture. A good night’s rest.','kd':'A little sharp. A little sparkling.','ld':'Thick enough to take your time.','fresh':'SLOW','heading':'Good things<br>take cultures.','story':'We start with milk and a living culture. Then we leave them alone. Time brings the tang, the texture and the character. No hurry. Just a different kind of fast food.','seal':'SMALL BATCH • LIVING CULTURE • ','step1':'Start simply.','step2':'Wait patiently.','step3':'Bring it back.','stepd1':'Milk and a carefully tended starter. A short list is the whole point.','stepd2':'Culture does its work. We check each batch for flavour and texture.','stepd3':'A glass jar worth keeping. Rinse it, reuse it, give it another life.','box':'Meet your<br>new daily culture.','boxcopy':'Choose a jar and build a sample tasting box. This is a fictional creamery concept; the calculator is a local demo and does not place an order.','product':'Your culture','quantity':'Number of jars','calculate':'Build my box ↗','result':'Your sample box: {n} jars of {p}. Total: {sum}. No order has been placed.','pause':'Pause seals','resume':'Resume seals','footer':'CULT / SLOW FOOD, EVERY DAY','concept':'FICTIONAL CREAMERY · DESIGN CONCEPT','jar':'RETURNABLE GLASS / 300 G','names':['Set yogurt','Slow kefir','Soft labneh']}
ru={'menu':'МЕНЮ','nav1':'Наши культуры','nav2':'Без спешки','nav3':'Собрать набор','small':'НЕМНОГО КУЛЬТУРЫ КАЖДЫЙ ДЕНЬ.','hero':'КУЛЬТУРА','yogurt':'01 / ГУСТОЙ ЙОГУРТ','kefir':'02 / МЕДЛЕННЫЙ КЕФИР','labneh':'03 / НЕЖНЫЙ ЛАБНЕ','yd':'Молоко. Закваска. Спокойная ночь.','kd':'Чуть кислее. Чуть игристее.','ld':'Густой — чтобы не торопиться.','fresh':'ТИШЕ','heading':'Хорошим вещам<br>нужна культура.','story':'Начинаем с молока и живой закваски. А потом оставляем их в покое. Время создаёт кислинку, текстуру и характер. Никакой спешки. Просто другая быстрая еда.','seal':'МАЛЫЙ ТИРАЖ • ЖИВАЯ КУЛЬТУРА • ','step1':'Начать с простого.','step2':'Подождать.','step3':'Вернуть в дело.','stepd1':'Молоко и закваска, за которой ухаживают. Короткий состав — в этом весь смысл.','stepd2':'Культура делает своё дело. Каждую партию проверяем на вкус и текстуру.','stepd3':'Банка, которую хочется сохранить. Вымойте, используйте снова, дайте ей вторую жизнь.','box':'Ваша новая<br>ежедневная культура.','boxcopy':'Выберите продукт и соберите пробный набор. Это концепция вымышленной мастерской; калькулятор работает локально и не оформляет заказ.','product':'Ваша культура','quantity':'Количество банок','calculate':'Собрать мой набор ↗','result':'Ваш пробный набор: {n} банок — {p}. Итого: {sum}. Заказ не оформлен.','pause':'Остановить печати','resume':'Продолжить движение','footer':'CULT / МЕДЛЕННАЯ ЕДА КАЖДЫЙ ДЕНЬ','concept':'ВЫМЫШЛЕННАЯ МАСТЕРСКАЯ · ДИЗАЙН-КОНЦЕПЦИЯ','jar':'ВОЗВРАТНОЕ СТЕКЛО / 300 Г','names':['Густой йогурт','Медленный кефир','Нежный лабне']}
def t(k,tag='span',attrs=''):return f'<{tag} data-i18n="{k}" {attrs}>{en[k]}</{tag}>'
def seal(n):
 return f'<div class="seal" aria-label="Small batch, living culture"><svg class="seal-spin" viewBox="0 0 140 140" aria-hidden="true"><defs><path id="circle{n}" d="M70,70m-51,0a51,51 0 1,1 102,0a51,51 0 1,1 -102,0"/></defs><circle cx="70" cy="70" r="67"/><text><textPath href="#circle{n}" textLength="315" data-i18n="seal">{en["seal"]}</textPath></text></svg><b>C.</b></div>'
css='''
/* Inter supplies Cyrillic; display geometry follows the photographed billboard. */
:root{--ui:'Inter',sans-serif;--product-stage:620px;--seal-size:140px;--spin-duration:24s}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--color-cream-white);color:var(--color-forest-heritage);font:var(--text-body-sm)/var(--leading-body-sm) var(--ui)}h1,h2,h3,p{margin:0}button,input,select{font:inherit;color:inherit}button,a{cursor:pointer}a{color:inherit;text-decoration:none}button{background:none;border:0}a:hover,button:hover{text-decoration:underline}:focus-visible{outline:2px solid var(--color-forest-heritage);outline-offset:5px}header{height:120px;display:flex;align-items:center;justify-content:space-between;padding:var(--spacing-30) var(--spacing-50);position:relative}.wordmark{position:absolute;left:50%;transform:translateX(-50%);font-size:60px;font-weight:900;font-style:italic;letter-spacing:-4px}.languages{display:flex;gap:var(--spacing-10);font-size:var(--text-caption)}[aria-pressed=true]{text-decoration:underline;text-underline-offset:4px}#menu-button{display:flex;align-items:center;gap:var(--spacing-12)}.bars{font-size:26px}#menu-panel{position:absolute;right:var(--spacing-50);top:100px;border:1px solid currentColor;background:var(--color-cream-white);padding:var(--spacing-24);z-index:5;min-width:250px}#menu-panel a{display:block;margin:var(--spacing-15) 0}[hidden]{display:none!important}.hero{position:relative;padding:var(--spacing-20) var(--spacing-30) 0}.small{text-align:center;font-size:var(--text-caption);letter-spacing:.08em;margin-bottom:var(--spacing-30)}h1{font-size:clamp(150px,15.4vw,230px);font-weight:900;line-height:var(--leading-display);letter-spacing:var(--tracking-display);text-align:center;color:var(--color-cream-teal);position:relative;z-index:0}.product-photo{display:block;width:100%;height:var(--product-stage);object-fit:contain;position:relative;margin-top:-80px;pointer-events:none}.product-row{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--element-gap);text-align:center;margin-top:-30px;position:relative;z-index:1}.product-row h2{display:inline-block;background:var(--color-cream-teal);font-size:var(--text-body-sm);font-weight:500;padding:var(--spacing-10) var(--spacing-20)}.product-row p{font-size:var(--text-caption);color:var(--color-charcoal-press);margin:var(--spacing-15) 0}.seal{width:var(--seal-size);height:var(--seal-size);position:relative}.hero>.seal{position:absolute;right:var(--spacing-30);top:0;z-index:2}.seal svg{width:100%;height:100%;overflow:visible;animation:seal-spin var(--spin-duration) linear infinite}.seal circle{fill:none;stroke:currentColor;stroke-width:1.5}.seal text{fill:currentColor;font-size:12px;letter-spacing:1.4px}.seal b{position:absolute;inset:0;display:grid;place-items:center;font-size:46px;font-style:italic;font-weight:900}.motion-paused .seal-spin{animation-play-state:paused}@keyframes seal-spin{to{transform:rotate(360deg)}}.story{max-width:var(--page-max-width);margin:var(--spacing-50) auto 0;padding:var(--spacing-50);position:relative}.billboard{font-size:var(--text-display);font-weight:900;line-height:var(--leading-display);letter-spacing:var(--tracking-display);color:var(--color-butter-yellow);text-align:center}.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:calc(var(--spacing-50)*2);margin-top:var(--spacing-50);align-items:center}.story h2{font-size:var(--text-subheading);line-height:var(--leading-subheading);letter-spacing:var(--tracking-subheading);font-weight:500}.story p{max-width:500px;font-size:var(--text-body-sm);color:var(--color-charcoal-press)}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--spacing-50);padding:var(--spacing-50);margin:var(--spacing-50) 0;border-top:1px solid currentColor;border-bottom:1px solid currentColor}.steps h3{font-size:var(--text-body-sm);font-weight:500;margin:var(--spacing-20) 0 var(--spacing-12)}.steps p{font-size:var(--text-caption);max-width:330px;color:var(--color-charcoal-press)}.steps .number{font-size:var(--text-subheading)}.box{display:grid;grid-template-columns:1fr 1fr;gap:calc(var(--spacing-50)*2);padding:var(--spacing-50);max-width:var(--page-max-width);margin:auto}.box h2{font-size:var(--text-subheading);line-height:var(--leading-subheading);font-weight:500;margin:var(--spacing-24) 0}.box p{max-width:470px;font-size:var(--text-caption)}.calculator{padding-top:var(--spacing-30)}label{display:block;font-size:var(--text-caption);margin-bottom:var(--spacing-10)}select,input{border:1px solid currentColor;border-radius:var(--radius-body);background:var(--color-cream-white);padding:var(--spacing-12);width:100%;margin-bottom:var(--spacing-24)}.outline{border:1.5px solid currentColor;border-radius:var(--radius-buttons);padding:var(--spacing-12) var(--spacing-24)}#order-result{margin-top:var(--spacing-24);min-height:60px}footer{display:flex;align-items:center;justify-content:space-between;padding:var(--spacing-30) var(--spacing-50);border-top:1px solid currentColor;font-size:var(--text-caption)}html[data-lang=ru] h1{font-size:195px}.hero .seal{--seal-size:120px}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.seal svg{animation:none}}
'''
body=f'''<header><div class="languages"><button data-lang="en" aria-pressed="true">EN</button><span>/</span><button data-lang="ru" aria-pressed="false">RU</button></div><a href="#" class="wordmark" aria-label="Cult home">Cult</a><button id="menu-button" aria-expanded="false" aria-controls="menu-panel"><span class="bars" aria-hidden="true">☰</span>{t('menu')}</button><nav id="menu-panel" hidden>{t('nav1','a','href="#cultures"')}{t('nav2','a','href="#story"')}{t('nav3','a','href="#box"')}</nav></header>
<main><section class="hero" id="cultures">{t('small','p','class="small"')}{t('hero','h1')}{seal(1)}<img class="product-photo" src="{photo}" alt="Three Cult jars: yogurt, kefir and labneh" width="1536" height="1024"><div class="product-row">'''+''.join(f'<article>{t(k,"h2")}{t(d,"p")}{t("jar","p")}</article>' for k,d in [('yogurt','yd'),('kefir','kd'),('labneh','ld')])+f'''</div></section>
<section class="story" id="story">{t('fresh','div','class="billboard"')}<div class="story-grid">{t('heading','h2')}{t('story','p')}</div></section><section class="steps">'''+''.join(f'<article><span class="number">0{i}</span>{t("step"+str(i),"h3")}{t("stepd"+str(i),"p")}</article>' for i in range(1,4))+f'''</section><section class="box" id="box"><div>{seal(2)}{t('box','h2')}{t('boxcopy','p')}</div><form class="calculator" id="box-form">{t('product','label','for="product-select"')}<select id="product-select"><option value="yogurt">Set yogurt — €4</option><option value="kefir">Slow kefir — €5</option><option value="labneh">Soft labneh — €6</option></select>{t('quantity','label','for="portion"')}<input id="portion" type="number" min="1" max="12" value="3" required>{t('calculate','button','id="calculate" class="outline" type="submit"')}<p id="order-result" role="status"></p></form></section></main><footer>{t('footer')}{t('concept')}<button id="motion-toggle" aria-pressed="false">{en['pause']}</button></footer>'''
js='''const I18N=__I18N__;let lang='en',paused=false;const menu=document.querySelector('#menu-button'),panel=document.querySelector('#menu-panel');function closeMenu(){panel.hidden=true;menu.setAttribute('aria-expanded','false')}menu.onclick=()=>{panel.hidden=!panel.hidden;menu.setAttribute('aria-expanded',!panel.hidden)};panel.querySelectorAll('a').forEach(a=>a.onclick=closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();menu.focus()}});document.addEventListener('click',e=>{if(!panel.contains(e.target)&&!menu.contains(e.target))closeMenu()});function apply(l){lang=l;document.documentElement.lang=l;document.documentElement.dataset.lang=l;document.querySelectorAll('[data-i18n]').forEach(e=>e.innerHTML=I18N[l][e.dataset.i18n]);document.querySelectorAll('button[data-lang]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lang===l));document.querySelectorAll('#product-select option').forEach((e,i)=>e.textContent=I18N[l].names[i]+' — €'+(i+4));document.querySelector('#motion-toggle').textContent=I18N[l][paused?'resume':'pause'];document.querySelector('#order-result').textContent=''}document.querySelectorAll('button[data-lang]').forEach(b=>b.onclick=()=>apply(b.dataset.lang));document.querySelector('#motion-toggle').onclick=()=>{paused=!paused;document.body.classList.toggle('motion-paused',paused);document.querySelector('#motion-toggle').setAttribute('aria-pressed',paused);document.querySelector('#motion-toggle').textContent=I18N[lang][paused?'resume':'pause']};document.querySelector('#box-form').onsubmit=e=>{e.preventDefault();const n=Number(document.querySelector('#portion').value);if(!Number.isInteger(n)||n<1||n>12)return;const i=document.querySelector('#product-select').selectedIndex;document.querySelector('#order-result').textContent=I18N[lang].result.replace('{n}',n).replace('{p}',I18N[lang].names[i]).replace('{sum}',new Intl.NumberFormat(lang,{style:'currency',currency:'EUR'}).format(n*(i+4)))};'''.replace('__I18N__',json.dumps({'en':en,'ru':ru},ensure_ascii=False))
license=(P.parents[2]/'motion-animation/motion_reference/originals/react-bits/LICENSE.md').read_text()
