(P/'index.html').write_text('<!doctype html><html lang="en" data-lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cult — A little culture every day</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;900&display=swap" rel="stylesheet"><style>'+tokens+css+'</style></head><body>'+body+'<script>'+js+'</script><!-- '+license+' --></body></html>')
